1	package indexroom
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"slices"
10		"unicode/utf8"
11	)
12	
13	// ErrInvalidSnapshot marks a rejected snapshot document: malformed or
14	// truncated JSON, trailing data after the object, an unknown version,
15	// missing, mistyped, unknown, or duplicated fields, a null where version,
16	// tip, height, hash, parent, or a transaction identifier is required,
17	// heights that do not ascend consecutively from 1, an empty or duplicated
18	// hash, a broken parent link, a version-2 timestamp that is missing or
19	// neither null nor a non-negative integer, a hash, parent, or transaction
20	// identifier whose JSON string carries invalid UTF-8 bytes or unpaired or
21	// misordered Unicode surrogate escapes, or a tip that disagrees with the
22	// block list. A rejected restore never changes the index.
23	var ErrInvalidSnapshot = errors.New("indexroom: invalid snapshot")
24	
25	const (
26		// snapshotVersion1 is the timestamp-less layout. It stays readable
27		// indefinitely; its blocks restore with missing timestamps.
28		snapshotVersion1 = 1
29		// snapshotVersion2 adds a required timestamp field to every block:
30		// either a non-negative Unix-seconds integer or null for missing time.
31		snapshotVersion2 = 2
32	)
33	
34	// snapshotDoc is the version-1 wire form of an exported main chain.
35	type snapshotDoc struct {
36		Version int64           `json:"version"`
37		Tip     int64           `json:"tip"`
38		Blocks  []snapshotBlock `json:"blocks"`
39	}
40	
41	// snapshotBlock is the version-1 wire form of one block.
42	type snapshotBlock struct {
43		Height int64    `json:"height"`
44		Hash   string   `json:"hash"`
45		Parent string   `json:"parent"`
46		Txs    []string `json:"txs"`
47	}
48	
49	// snapshotDocV2 is the timestamp-bearing wire form.
50	type snapshotDocV2 struct {
51		Version int64             `json:"version"`
52		Tip     int64             `json:"tip"`
53		Blocks  []snapshotBlockV2 `json:"blocks"`
54	}
55	
56	// snapshotBlockV2 is the version-2 wire form of one block. A nil Timestamp
57	// serializes as null.
58	type snapshotBlockV2 struct {
59		Height    int64    `json:"height"`
60		Hash      string   `json:"hash"`
61		Parent    string   `json:"parent"`
62		Txs       []string `json:"txs"`
63		Timestamp *int64   `json:"timestamp"`
64	}
65	
66	// Export writes the current main chain to w as a JSON snapshot: a single
67	// object with version, tip, and the blocks ordered by ascending height, each
68	// carrying its transactions in order. The same main chain always produces
69	// the same bytes, regardless of the reorg, restore, or query history that
70	// led to it. Only blocks in effect at export time appear; nothing the index
71	// once held and later dropped is included.
72	//
73	// A chain whose blocks all lack timestamps keeps the original version-1
74	// layout, byte for byte. As soon as any block carries a timestamp the
75	// document is version 2 and every block includes a timestamp field: a
76	// non-negative integer or null for a missing timestamp.
77	//
78	// Export observes one complete chain state and never modifies the index.
79	// The chain is copied under the lock and serialized afterwards, so queries
80	// and appends proceed while the stream is still being written. A write
81	// failure is reported and leaves the index untouched.
82	func (index *Index) Export(w io.Writer) error {
83		index.mu.Lock()
84		version := int64(snapshotVersion1)
85		for height := int64(1); height <= index.Tip; height++ {
86			if index.Blocks[height].Time != nil {
87				version = snapshotVersion2
88				break
89			}
90		}
91		var raw []byte
92		var err error
93		if version == snapshotVersion1 {
94			doc := snapshotDoc{
95				Version: snapshotVersion1,
96				Tip:     index.Tip,
97				Blocks:  make([]snapshotBlock, 0, int(index.Tip)),
98			}
99			for height := int64(1); height <= index.Tip; height++ {
100				block := index.Blocks[height]
101				txs := make([]string, len(block.Txs))
102				copy(txs, block.Txs)
103				doc.Blocks = append(doc.Blocks, snapshotBlock{
104					Height: block.Height,
105					Hash:   block.Hash,
106					Parent: block.Parent,
107					Txs:    txs,
108				})
109			}
110			index.mu.Unlock()
111			raw, err = json.Marshal(doc)
112		} else {
113			doc := snapshotDocV2{
114				Version: snapshotVersion2,
115				Tip:     index.Tip,
116				Blocks:  make([]snapshotBlockV2, 0, int(index.Tip)),
117			}
118			for height := int64(1); height <= index.Tip; height++ {
119				block := index.Blocks[height]
120				txs := make([]string, len(block.Txs))
121				copy(txs, block.Txs)
122				entry := snapshotBlockV2{
123					Height: block.Height,
124					Hash:   block.Hash,
125					Parent: block.Parent,
126					Txs:    txs,
127				}
128				if block.Time != nil {
129					t := *block.Time
130					entry.Timestamp = &t
131				}
132				doc.Blocks = append(doc.Blocks, entry)
133			}
134			index.mu.Unlock()
135			raw, err = json.Marshal(doc)
136		}
137		if err != nil {
138			panic(err) // snapshot docs only contain marshalable fields
139		}
140		n, err := w.Write(raw)
141		if err != nil {
142			return fmt.Errorf("indexroom: export snapshot: %w", err)
143		}
144		if n != len(raw) {
145			return fmt.Errorf("indexroom: export snapshot: %w", io.ErrShortWrite)
146		}
147		return nil
148	}
149	
150	// Restore replaces the whole main chain with the snapshot read from r. The
151	// input must be exactly one snapshot object, optionally followed by
152	// whitespace; every block is validated — including heights ascending from 1,
153	// non-empty unique hashes, and parent linkage — before anything is applied.
154	// The first block's parent is exempt from linkage: it names the chain start
155	// and need not be indexed.
156	//
157	// The replacement takes effect as one complete operation: on success the
158	// index holds exactly the snapshot chain with no leftover heights or hashes,
159	// and on any failure — a read error or an invalid block discovered at the
160	// very end — the current chain and every previously issued cursor remain as
161	// they were. The stream is consumed and validated before the lock is taken,
162	// so the index stays queryable and appendable while the restore is reading.
163	//
164	// After a successful restore, cursors issued earlier by this same index keep
165	// working wherever the pinned range still matches and the tip still covers
166	// it; otherwise continuations fail with ErrQueryChanged as usual.
167	func (index *Index) Restore(r io.Reader) error {
168		tip, blocks, err := parseSnapshot(r)
169		if err != nil {
170			return err
171		}
172		stored := make(map[int64]Block, len(blocks))
173		byHash := make(map[string]int64, len(blocks))
174		for _, block := range blocks {
175			stored[block.Height] = block
176			byHash[block.Hash] = block.Height
177		}
178		index.mu.Lock()
179		index.Blocks = stored
180		index.ByHash = byHash
181		index.Tip = tip
182		index.mu.Unlock()
183		return nil
184	}
185	
186	// parseSnapshot reads and fully validates one snapshot document. It returns
187	// the tip height and the validated blocks in ascending height order.
188	func parseSnapshot(r io.Reader) (int64, []Block, error) {
189		dec := json.NewDecoder(r)
190		tok, err := dec.Token()
191		if err != nil {
192			return 0, nil, classifySnapshotErr(err)
193		}
194		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
195			return 0, nil, invalidSnapshot("snapshot must be a single JSON object")
196		}
197	
198		// Top-level fields are captured raw so blocks can be parsed with the
199		// strict schema matching the declared version, whatever the field order,
200		// and so null can be told apart from a zero value.
201		var (
202			rawVersion, rawTip   json.RawMessage
203			rawBlocks            json.RawMessage
204			haveVersion, haveTip bool
205			haveBlocks           bool
206			seen                 = map[string]bool{}
207		)
208		for dec.More() {
209			key, err := snapshotKey(dec)
210			if err != nil {
211				return 0, nil, err
212			}
213			if seen[key] {
214				return 0, nil, invalidSnapshot("duplicate field %q", key)
215			}
216			seen[key] = true
217			switch key {
218			case "version":
219				if err := dec.Decode(&rawVersion); err != nil {
220					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
221				}
222				haveVersion = true
223			case "tip":
224				if err := dec.Decode(&rawTip); err != nil {
225					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
226				}
227				haveTip = true
228			case "blocks":
229				if err := dec.Decode(&rawBlocks); err != nil {
230					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
231				}
232				haveBlocks = true
233			default:
234				return 0, nil, invalidSnapshot("unknown field %q", key)
235			}
236		}
237		if _, err := dec.Token(); err != nil { // closing '}'
238			return 0, nil, classifySnapshotErr(err)
239		}
240		// Only whitespace may follow the snapshot object.
241		if _, err := dec.Token(); err != io.EOF {
242			if err == nil {
243				return 0, nil, invalidSnapshot("trailing data after the snapshot object")
244			}
245			return 0, nil, classifySnapshotErr(err)
246		}
247	
248		if !haveVersion {
249			return 0, nil, invalidSnapshot("missing field %q", "version")
250		}
251		if !haveTip {
252			return 0, nil, invalidSnapshot("missing field %q", "tip")
253		}
254		if !haveBlocks {
255			return 0, nil, invalidSnapshot("missing field %q", "blocks")
256		}
257		version, err := snapshotInt64(rawVersion, "version")
258		if err != nil {
259			return 0, nil, err
260		}
261		tip, err := snapshotInt64(rawTip, "tip")
262		if err != nil {
263			return 0, nil, err
264		}
265		if version != snapshotVersion1 && version != snapshotVersion2 {
266			return 0, nil, invalidSnapshot("unsupported version %d", version)
267		}
268	
269		blockDec := json.NewDecoder(bytes.NewReader(rawBlocks))
270		blocks, err := parseSnapshotBlocks(blockDec, version)
271		if err != nil {
272			return 0, nil, err
273		}
274		if _, err := blockDec.Token(); err != io.EOF {
275			if err == nil {
276				return 0, nil, invalidSnapshot("trailing data after the blocks array")
277			}
278			return 0, nil, classifySnapshotErr(err)
279		}
280	
281		lastHeight := int64(0)
282		if len(blocks) > 0 {
283			lastHeight = blocks[len(blocks)-1].Height
284		}
285		if tip != lastHeight {
286			return 0, nil, invalidSnapshot("tip %d does not match the last block height %d", tip, lastHeight)
287		}
288		return tip, blocks, nil
289	}
290	
291	// parseSnapshotBlocks reads the blocks array value, validating heights,
292	// hashes, parent links, and (for version 2) timestamps as it goes.
293	func parseSnapshotBlocks(dec *json.Decoder, version int64) ([]Block, error) {
294		tok, err := dec.Token()
295		if err != nil {
296			return nil, classifySnapshotErr(err)
297		}
298		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
299			return nil, invalidSnapshot("field %q must be an array", "blocks")
300		}
301		blocks := []Block{}
302		seenHash := map[string]bool{}
303		for dec.More() {
304			var block Block
305			if version == snapshotVersion2 {
306				block, err = parseSnapshotBlockV2(dec)
307			} else {
308				block, err = parseSnapshotBlock(dec)
309			}
310			if err != nil {
311				return nil, err
312			}
313			want := int64(len(blocks) + 1)
314			if block.Height != want {
315				return nil, invalidSnapshot("block height %d out of order, expected %d", block.Height, want)
316			}
317			if block.Hash == "" {
318				return nil, invalidSnapshot("block at height %d has an empty hash", block.Height)
319			}
320			if seenHash[block.Hash] {
321				return nil, invalidSnapshot("duplicate hash %q", block.Hash)
322			}
323			seenHash[block.Hash] = true
324			// The first block's parent names the chain start and is exempt from
325			// linkage; every later block must point at its predecessor.
326			if len(blocks) > 0 && block.Parent != blocks[len(blocks)-1].Hash {
327				return nil, invalidSnapshot("block at height %d does not link to its parent", block.Height)
328			}
329			blocks = append(blocks, block)
330		}
331		if _, err := dec.Token(); err != nil { // closing ']'
332			return nil, classifySnapshotErr(err)
333		}
334		return blocks, nil
335	}
336	
337	// parseSnapshotBlock reads one version-1 block object, requiring exactly the
338	// fields height, hash, parent, and txs.
339	func parseSnapshotBlock(dec *json.Decoder) (Block, error) {
340		var block Block
341		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs")
342		if err != nil {
343			return block, err
344		}
345		return finishSnapshotBlock(fields)
346	}
347	
348	// parseSnapshotBlockV2 reads one version-2 block object, requiring exactly
349	// the fields height, hash, parent, txs, and timestamp. Timestamp must be
350	// null or a non-negative integer; the block returns a nil time for null.
351	func parseSnapshotBlockV2(dec *json.Decoder) (Block, error) {
352		var block Block
353		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs", "timestamp")
354		if err != nil {
355			return block, err
356		}
357		if _, ok := fields["timestamp"]; !ok {
358			return block, invalidSnapshot("block is missing field %q", "timestamp")
359		}
360		block, err = finishSnapshotBlock(fields)
361		if err != nil {
362			return block, err
363		}
364		t, err := parseSnapshotTimestamp(fields["timestamp"])
365		if err != nil {
366			return Block{}, err
367		}
368		block.Time = t
369		return block, nil
370	}
371	
372	// readSnapshotBlockObject reads one block object and captures each known
373	// field's raw value. Fields are decoded only after the whole object is read,
374	// so a null can be rejected per field and a txs element error can name the
375	// block's height whatever order the fields arrive in.
376	func readSnapshotBlockObject(dec *json.Decoder, known ...string) (map[string]json.RawMessage, error) {
377		tok, err := dec.Token()
378		if err != nil {
379			return nil, classifySnapshotErr(err)
380		}
381		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
382			return nil, invalidSnapshot("block must be a JSON object")
383		}
384		fields := map[string]json.RawMessage{}
385		for dec.More() {
386			key, err := snapshotKey(dec)
387			if err != nil {
388				return nil, err
389			}
390			if _, dup := fields[key]; dup {
391				return nil, invalidSnapshot("duplicate block field %q", key)
392			}
393			if !slices.Contains(known, key) {
394				return nil, invalidSnapshot("unknown block field %q", key)
395			}
396			var raw json.RawMessage
397			if err := dec.Decode(&raw); err != nil {
398				return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
399			}
400			fields[key] = raw
401		}
402		if _, err := dec.Token(); err != nil { // closing '}'
403			return nil, classifySnapshotErr(err)
404		}
405		return fields, nil
406	}
407	
408	// finishSnapshotBlock decodes the shared block fields from their raw values,
409	// requiring height, hash, parent, and txs and rejecting null for each.
410	func finishSnapshotBlock(fields map[string]json.RawMessage) (Block, error) {
411		var block Block
412		for _, field := range []string{"height", "hash", "parent", "txs"} {
413			if _, ok := fields[field]; !ok {
414				return block, invalidSnapshot("block is missing field %q", field)
415			}
416		}
417		var err error
418		if block.Height, err = snapshotInt64(fields["height"], "height"); err != nil {
419			return block, err
420		}
421		if block.Hash, err = snapshotString(fields["hash"], "hash", block.Height); err != nil {
422			return block, err
423		}
424		if block.Parent, err = snapshotString(fields["parent"], "parent", block.Height); err != nil {
425			return block, err
426		}
427		txs, err := parseSnapshotTxs(json.NewDecoder(bytes.NewReader(fields["txs"])), block.Height)
428		if err != nil {
429			return block, err
430		}
431		block.Txs = txs
432		return block, nil
433	}
434	
435	// snapshotInt64 decodes one required integer field, rejecting null rather
436	// than letting it pass as zero.
437	func snapshotInt64(raw json.RawMessage, field string) (int64, error) {
438		if isSnapshotNull(raw) {
439			return 0, invalidSnapshot("field %q must not be null", field)
440		}
441		var v int64
442		if err := json.Unmarshal(raw, &v); err != nil {
443			return 0, classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
444		}
445		return v, nil
446	}
447	
448	// snapshotString decodes one required string field, rejecting null rather
449	// than letting it pass as the empty string. The raw literal is also checked
450	// for invalid UTF-8 bytes and unpaired or misordered \uXXXX surrogate
451	// escapes, which the decoder would otherwise silently rewrite to U+FFFD;
452	// height identifies the block the field belongs to in the error.
453	func snapshotString(raw json.RawMessage, field string, height int64) (string, error) {
454		if isSnapshotNull(raw) {
455			return "", invalidSnapshot("field %q must not be null", field)
456		}
457		var s string
458		if err := json.Unmarshal(raw, &s); err != nil {
459			return "", classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
460		}
461		if !validSnapshotString(raw) {
462			return "", invalidSnapshot("block at height %d: field %q has invalid UTF-8 or unpaired surrogate escapes", height, field)
463		}
464		return s, nil
465	}
466	
467	// isSnapshotNull reports whether a raw field value is the JSON null literal.
468	func isSnapshotNull(raw json.RawMessage) bool {
469		return string(raw) == "null"
470	}
471	
472	// validSnapshotString reports whether raw is a JSON string literal whose
473	// content is valid UTF-8 and whose \uXXXX escapes contain no unpaired or
474	// misordered surrogates. The JSON decoder accepts both defects silently,
475	// rewriting the bad parts to U+FFFD, which could merge distinct identifiers;
476	// the raw bytes are checked here before the decoded value is trusted. A
477	// genuine U+FFFD — written literally or as a \ufffd escape — is valid
478	// UTF-8 and passes.
479	func validSnapshotString(raw json.RawMessage) bool {
480		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
481			return false
482		}
483		body := raw[1 : len(raw)-1]
484		for i := 0; i < len(body); {
485			b := body[i]
486			switch {
487			case b == '\\':
488				if i+1 >= len(body) {
489					return false
490				}
491				if body[i+1] != 'u' {
492					i += 2 // \", \\, \/, \b, \f, \n, \r, \t
493					continue
494				}
495				code, ok := snapshotHex4(body, i+2)
496				if !ok {
497					return false
498				}
499				i += 6
500				switch {
501				case code >= 0xD800 && code <= 0xDBFF:
502					// A high surrogate is only valid as the first half of a
503					// pair; the low half must follow immediately as an escape.
504					if i+6 > len(body) || body[i] != '\\' || body[i+1] != 'u' {
505						return false
506					}
507					low, ok := snapshotHex4(body, i+2)
508					if !ok || low < 0xDC00 || low > 0xDFFF {
509						return false
510					}
511					i += 6
512				case code >= 0xDC00 && code <= 0xDFFF:
513					return false // a low surrogate cannot appear on its own
514				}
515			case b < utf8.RuneSelf:
516				i++
517			default:
518				// DecodeRune returns RuneError with size 1 for invalid
519				// encoding; a genuine U+FFFD decodes with size 3.
520				r, size := utf8.DecodeRune(body[i:])
521				if r == utf8.RuneError && size <= 1 {
522					return false
523				}
524				i += size
525			}
526		}
527		return true
528	}
529	
530	// snapshotHex4 reads four hexadecimal digits starting at b[i].
531	func snapshotHex4(b []byte, i int) (rune, bool) {
532		if i+4 > len(b) {
533			return 0, false
534		}
535		var v rune
536		for _, c := range b[i : i+4] {
537			var d byte
538			switch {
539			case '0' <= c && c <= '9':
540				d = c - '0'
541			case 'a' <= c && c <= 'f':
542				d = c - 'a' + 10
543			case 'A' <= c && c <= 'F':
544				d = c - 'A' + 10
545			default:
546				return 0, false
547			}
548			v = v*16 + rune(d)
549		}
550		return v, true
551	}
552	
553	// parseSnapshotTimestamp reads one timestamp value: null for a missing
554	// timestamp, or a non-negative integer. Zero is stored as a real timestamp,
555	// distinct from null.
556	func parseSnapshotTimestamp(raw json.RawMessage) (*int64, error) {
557		var t *int64
558		if err := json.Unmarshal(raw, &t); err != nil {
559			return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", "timestamp", err))
560		}
561		if t != nil && *t < 0 {
562			return nil, invalidSnapshot("timestamp must not be negative")
563		}
564		return t, nil
565	}
566	
567	// parseSnapshotTxs reads one txs array, preserving duplicates and empty
568	// identifiers exactly as written. A null element is rejected, naming the
569	// block's height and the element's zero-based position, and so is an
570	// element whose raw string carries invalid UTF-8 bytes or unpaired or
571	// misordered surrogate escapes.
572	func parseSnapshotTxs(dec *json.Decoder, height int64) ([]string, error) {
573		tok, err := dec.Token()
574		if err != nil {
575			return nil, classifySnapshotErr(err)
576		}
577		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
578			return nil, invalidSnapshot("field %q must be an array of strings", "txs")
579		}
580		txs := []string{}
581		for dec.More() {
582			var raw json.RawMessage
583			if err := dec.Decode(&raw); err != nil {
584				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
585			}
586			if isSnapshotNull(raw) {
587				return nil, invalidSnapshot("block at height %d: txs element %d must not be null", height, len(txs))
588			}
589			var tx string
590			if err := json.Unmarshal(raw, &tx); err != nil {
591				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
592			}
593			if !validSnapshotString(raw) {
594				return nil, invalidSnapshot("block at height %d: field %q element %d has invalid UTF-8 or unpaired surrogate escapes", height, "txs", len(txs))
595			}
596			txs = append(txs, tx)
597		}
598		if _, err := dec.Token(); err != nil { // closing ']'
599			return nil, classifySnapshotErr(err)
600		}
601		return txs, nil
602	}
603	
604	// snapshotKey reads the next object key.
605	func snapshotKey(dec *json.Decoder) (string, error) {
606		tok, err := dec.Token()
607		if err != nil {
608			return "", classifySnapshotErr(err)
609		}
610		key, ok := tok.(string)
611		if !ok {
612			return "", invalidSnapshot("object key must be a string")
613		}
614		return key, nil
615	}
616	
617	// invalidSnapshot builds an ErrInvalidSnapshot error with a specific reason.
618	func invalidSnapshot(format string, args ...any) error {
619		return fmt.Errorf("%w: %s", ErrInvalidSnapshot, fmt.Sprintf(format, args...))
620	}
621	
622	// classifySnapshotErr maps decoder failures onto the snapshot error model:
623	// malformed JSON, wrong value types, and truncation are snapshot errors,
624	// while anything else is an underlying read failure reported as-is.
625	func classifySnapshotErr(err error) error {
626		var syntaxErr *json.SyntaxError
627		var typeErr *json.UnmarshalTypeError
628		switch {
629		case errors.As(err, &syntaxErr), errors.As(err, &typeErr):
630			return fmt.Errorf("%w: %v", ErrInvalidSnapshot, err)
631		case errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF):
632			return fmt.Errorf("%w: unexpected end of input", ErrInvalidSnapshot)
633		default:
634			return fmt.Errorf("indexroom: read snapshot: %w", err)
635		}
636	}
637

