231	// gateWriteOutcome is what a blockingGateWriter returns from its one blocked
232	// Write call.
233	type gateWriteOutcome struct {
234		accepted int
235		err      error
236	}
237	
238	// blockingGateWriter silently accepts up to prefix bytes of the first write,
239	// records them, signals entered, and then blocks until the test releases it
240	// with a fixed return value. Export performs exactly one Write, which is all
241	// this writer needs to support.
242	type blockingGateWriter struct {
243		prefix   int
244		entered  chan struct{}
245		release  chan gateWriteOutcome
246		received bytes.Buffer
247	}
248	
249	func (w *blockingGateWriter) Write(p []byte) (int, error) {
250		n := w.prefix
251		if n > len(p) {
252			n = len(p)
253		}
254		w.received.Write(p[:n])
255		close(w.entered)
256		out := <-w.release
257		if out.accepted > len(p) {
258			out.accepted = len(p)
259		}
260		return out.accepted, out.err
261	}
262	
263	// startTimedExportReorgedMidStream builds an old chain whose only non-missing
264	// timestamp sits on the block about to be reorged away, starts an export into
265	// a gate blocked after 16 bytes, performs the reorg while the export is open,
266	// and verifies every observable state along the way. The post-reorg chain is
267	// entirely untimed, so a fresh export switches from version 2 to version 1.
268	func startTimedExportReorgedMidStream(t *testing.T) (*Index, string, *blockingGateWriter, <-chan error) {
269		t.Helper()
270		index := chain(t,
271			Block{Height: 1, Hash: "old-a", Parent: "genesis", Txs: []string{"old-a-tx"}},
272			Block{Height: 2, Hash: "old-b", Parent: "old-a", Txs: []string{"old-b-tx"}, Time: intptr(1700000000)},
273		)
274		wantOld := exportString(t, index)
275		if !strings.Contains(wantOld, `"version":2`) || len(wantOld) <= 17 {
276			t.Fatalf("test setup: old snapshot too small or not v2: %s", wantOld)
277		}
278	
279		writer := &blockingGateWriter{
280			prefix:  16,
281			entered: make(chan struct{}),
282			release: make(chan gateWriteOutcome),
283		}
284		done := make(chan error, 1)
285		go func() {
286			done <- index.Export(writer)
287		}()
288		<-writer.entered
289		if got := writer.received.String(); got != wantOld[:16] {
290			t.Fatalf("in-flight prefix=%q, want old-chain prefix %q", got, wantOld[:16])
291		}
292		assertExportStillRunning(t, done)
293	
294		dropped, err := index.Reorg([]Block{
295			{Height: 2, Hash: "new-b", Parent: "old-a", Txs: []string{"new-b-tx", "", "new-b-tx"}},
296		})
297		if err != nil {
298			t.Fatalf("reorg while export blocked refused: %v", err)
299		}
300		if !reflect.DeepEqual(dropped, []int64{2}) {
301			t.Fatalf("dropped=%v, want [2]", dropped)
302		}
303		assertExportStillRunning(t, done)
304		return index, wantOld, writer, done
305	}
306	
307	// requireCurrentChainIsReplacement verifies the reorg survived and the
308	// current main chain is the untimed replacement, including through a fresh
309	// export that must be version 1 with no timestamp residue.
310	func requireCurrentChainIsReplacement(t *testing.T, index *Index) {
311		t.Helper()
312		if index.Tip != 2 {
313			t.Fatalf("tip=%d, want 2", index.Tip)
314		}
315		block := index.Blocks[2]
316		if block.Hash != "new-b" || block.Parent != "old-a" || block.Time != nil {
317			t.Fatalf("height 2=%+v, want new-b without a timestamp", block)
318		}
319		if !reflect.DeepEqual(block.Txs, []string{"new-b-tx", "", "new-b-tx"}) {
320			t.Fatalf("replacement txs=%q", block.Txs)
321		}
322		if _, ok := index.ByHash["old-b"]; ok {
323			t.Fatal("reorged-away hash old-b still indexed")
324		}
325		page, err := index.QueryTxs(TxQuery{TxIDs: []string{"old-b-tx"}})
326		if err != nil || page.TotalMatches != 0 {
327			t.Fatalf("old tx still queryable: %+v err=%v", page, err)
328		}
329		page, err = index.QueryTxs(TxQuery{TxIDs: []string{"new-b-tx"}})
330		if err != nil || page.TotalMatches != 2 {
331			t.Fatalf("new tx matches=%d err=%v, want 2", page.TotalMatches, err)
332		}
333		raw := exportString(t, index)
334		want := `{"version":1,"tip":2,"blocks":[` +
335			`{"height":1,"hash":"old-a","parent":"genesis","txs":["old-a-tx"]},` +
336			`{"height":2,"hash":"new-b","parent":"old-a","txs":["new-b-tx","","new-b-tx"]}` +
337			`]}`
338		if raw != want {
339			t.Fatalf("post-reorg export=%s\nwant=%s", raw, want)
340		}
341		if strings.Contains(raw, "timestamp") {
342			t.Fatalf("post-reorg snapshot still carries a timestamp field: %s", raw)
343		}
344	}
345	
346	func TestExportSinkFailureAfterReorgKeepsReorg(t *testing.T) {
347		t.Run("sink returns concrete error", func(t *testing.T) {
348			index, _, writer, done := startTimedExportReorgedMidStream(t)
349			boom := errors.New("sink disk full")
350			writer.release <- gateWriteOutcome{accepted: 16, err: boom}
351			if err := <-done; !errors.Is(err, boom) {
352				t.Fatalf("export err=%v, want the sink error", err)
353			}
354			// The completed reorg stands; the failed export changed nothing.
355			requireCurrentChainIsReplacement(t, index)
356		})
357	
358		t.Run("sink accepts only some bytes with no error", func(t *testing.T) {
359			index, wantOld, writer, done := startTimedExportReorgedMidStream(t)
360			// Honest short write: the sink keeps only the 16 buffered bytes of
361			// the document and returns nil instead of an error.
362			writer.release <- gateWriteOutcome{accepted: 16, err: nil}
363			if 16 >= len(wantOld) {
364				t.Fatalf("test setup: accepted bytes must be below %d", len(wantOld))
365			}
366			if err := <-done; !errors.Is(err, io.ErrShortWrite) {
367				t.Fatalf("export err=%v, want io.ErrShortWrite", err)
368			}
369			requireCurrentChainIsReplacement(t, index)
370		})
371	}
