// snapshotDoc is the wire form of an exported main chain. Both layout
// versions share one shape: Version selects whether every block carries its
// Timestamp field.
type snapshotDoc struct {
	Version int64           `json:"version"`
	Tip     int64           `json:"tip"`
	Blocks  []snapshotBlock `json:"blocks"`
}

// snapshotBlock is the wire form of one block. Height, hash, parent, and the
// transaction list are shared by both versions. Timestamp is version 2 only:
// it serializes after txs, as a non-negative Unix-seconds integer or, when
// nil, as null for a missing time; omitempty keeps it absent from version 1
// entirely.
type snapshotBlock struct {
	Height    int64    `json:"height"`
	Hash      string   `json:"hash"`
	Parent    string   `json:"parent"`
	Txs       []string `json:"txs"`
	Timestamp *int64   `json:"timestamp,omitempty"`
}

